public static double[] toPrimitive(final Double[] array) {
    // Check if the input array is null
    if (array == null) {
        return null; // Return null if input array is null
    }

    // Create a new double array to place the primitive values
    double primitives[] = new double[array.length];
    for (int i = 0; i < array.length; i++) {
        // Convert each Double object to a primitive double and store in the new array
        primitives[i] = array[i].doubleValue();
    }

    return primitives; // Return the new double array containing primitive values
}

