    if(str == null || prefix == null || str.length() < prefix.length()){
        return false;
    }

    int prefixIndex = 0;
    for(int i = 0; i < str.length(); i++){
        char strChar = str.charAt(i);
        char prefixChar = prefix.charAt(prefixIndex);

        if(!ignoreCase && strChar != prefixChar){
            return false;
        }

        if(ignoreCase && Character.toLowerCase(strChar) != Character.toLowerCase(prefixChar)){
            return false;
        }

        prefixIndex++;
    }

    return true;
}

