    double halfWidth = box.getWidth() / 2.0;
    AffineTransform xTransform = AffineTransform.getTranslateInstance(-halfWidth, 0);
    AffineTransform mirrorTransform = AffineTransform.getTranslateInstance(halfWidth, 0).getInverse();

    Box2D leftBox = xTransform.createTransformedShape(box);
    Box2D rightBox = mirrorTransform.createTransformedShape(box);

    return Pair.of(leftBox, rightBox);
}

