private static <V,E> boolean isClique(Graph<V,E> graph,Set<V> vertices) {
    int n = vertices.size();
    if (n <= 1) {
        return true; // A set with 0 or 1 elements is trivially a clique.
    }

    List<V> edges = new ArrayList<>();
    for (E edge : graph.edgeSet()) {
        edges.add(edge.getSource());
        edges.add(edge.getTarget());
    }

    for (V vertex1 : vertices) {
        Set<V> neighbors = new HashSet<>(graph.neighbors(vertex1));
        for (V vertex2 : vertices) {
            if (vertex1 != vertex2 && !neighbors.contains(vertex2)) {
                return false; // Check each pair of vertices.
            }
        }
    }

    return true;
}

