public static String applyRelativePath(String path, String relativePath) {
    // Ensure the relative path starts with a slash if it's at the beginning or ends with a slash
    if (relativePath.startsWith("/") || relativePath.endsWith("/")) {
        relativePath = "/" + relativePath;
    }
    // Split the paths into arrays based on "/"
    String[] pathPaths = path.split("/");
    String[] relativePaths = relativePath.split("/");
    // Iterate until the relative paths length is either zero or less than the path paths length
    for (int i = 0; i < relativePaths.length && i < pathPaths.length; i++) {
        // If the relative paths current index is equal to the path paths current index, add it to the path paths
        if (i == relativePaths.length - 1 || relativePaths[i].equals(pathPaths[i])) {
            pathPaths[i + 1] = relativePaths[i + 1];
        } else {
            // Otherwise, add the relative paths current index to the path paths
            pathPaths = Arrays.copyOf(pathPaths, pathPaths.length + 1);
            int last_index = pathPaths.length - 1;
            if (relativePaths[i].equals("..")) {
                // If it is "..", decrement the last_index
                last_index--;
            } else if (relativePaths[i].equals(".")) {
                // If it is ".", continue
                continue;
            }
            pathPaths[last_index] = relativePaths[i];
        }
    }
    // Join the path paths with "/" and return the result
    return String.join("/", pathPaths);
}

