        if (table == null || pane == null) {
            throw new IllegalArgumentException("Table and JScrollPane cannot be null");
        }

        if (!(table.getParent() instanceof JScrollPane)) {
            throw new IllegalArgumentException("Table is not in a JScrollPane");
        }

        if (table.isEditing()) {
            throw new IllegalStateException("Table is being edited");
        }

        try {
            TableRowSorter<TableModel> sorter = (TableRowSorter<TableModel>) table.getRowSorter();
            sorter toggleSortOrder(row);
            sorter.clearExtendedSelection();
            selectionModel.setSelectedRow(row);
            table.getSelectionModel().setSelectionInterval(row, row);
            selectionModel.addSelectionInterval(row, row);
            if (sorter != null) {
                sorter.sortAndScrollToSortIndex(row);
            } else {
                pane.getVerticalScrollBar().setValue(pane.getVerticalScrollBar().getValue() + table.getRowHeight row));
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

