private void check(String modelName) throws IllegalStateException {
    Logger logger = Logger.getLogger(getClass().getName());

    // Check if the model name is null
    if (modelName == null) {
        throw new IllegalArgumentException("Model name cannot be null.");
    }

    // Check if the model name is empty
    if (modelName.isEmpty()) {
        throw new IllegalArgumentException("Model name cannot be empty.");
    }

    // Check if the model name has words separated by spaces
    if (!modelName.matches("\\S+ ")) {
        throw new IllegalArgumentException("Model name should contain words separated by spaces.");
    }

    // Check if the model name has the same number of numeric and non-numeric characters
    int numericCount = 0;
    int nonNumericCount = 0;
    for (char ch : modelName.toCharArray()) {
        if (Character.isDigit(ch)) {
            numericCount++;
        } else {
            nonNumericCount++;
        }
    }
    if (numericCount != nonNumericCount) {
        throw new IllegalStateException("Model name should have the same number of numeric and non-numeric characters.");
    }

    // Check if the model name has repeated characters
    char[] chars = modelName.toCharArray();
    for (int i = 0; i < chars.length; i++) {
        for (int j = i + 1; j < chars.length; j++) {
            if (chars[i] == chars[j]) {
                throw new IllegalStateException("Model name should not have repeated characters.");
            }
        }
    }

    // Check if the model name has continuing numeric characters
    for (int i = 0; i < chars.length - 1; i++) {
        if (Character.isDigit(chars[i]) && Character.isDigit(chars[i + 1])) {
            throw new IllegalStateException("Model name should not have continuing numeric characters.");
        }
    }

    // Check if the model name has multiple consecutive spaces
    Matcher matcher = Pattern.compile("\\s{2,}").matcher(modelName);
    if (matcher.find()) {
        throw new IllegalStateException("Model name should not have multiple consecutive spaces.");
    }
}

