    byte[] utf8Bytes = str.toString().getBytes(StandardCharsets.UTF_8);

    // Write the UTF-8 encoded bytes into the LinkedBuffer
    while (utf8Bytes.length > 0) {
        int remaining = utf8Bytes.length;
        for (int i = 0; i < 4; i++) {
            int time = i < remaining ? 0xFF : 0x00;
            time = (time << 8) | ((i + 1) < remaining ? utf8Bytes[i + 1] & 0xFF : 0x00);
            time = (time << 8) | ((i + 2) < remaining ? utf8Bytes[i + 2] & 0xFF : 0x00);
