public static void writeUTF8(final CharSequence str,final WriteSession session,final LinkedBuffer lb){
    //we first get the encoded length
    final int utf8Len = Utf8Util.encodeLength(str);
    //we then get the current size of the linked buffer
    int inCurrentSize = lb.getCurrentSize();
    //we then allocate sufficient space to fit the utf8Bytes with the size of the utf8Len
    if(inCurrentSize < utf8Len){
        lb.reserve(utf8Len-inCurrentSize);
    }
    //we then get the output array as the ByteBuffer.writeUTF8 method stores the utf8 bytes
    byte[] utf8Bytes = lb.currentBuffer().array();
    //we then with the input string and the utf8 bytes length, we call the WriteSession.write method to write the utf8 bytes to the LinkedBuffer's ByteBuffer.
    session.write(str,new byte [utf8Len]);
    //we then return the LinkedBuffer
    return lb;
}

