public long readRawVarint64() throws IOException {
    long result = 0;
    int shift = 0;
    while (true) {
        int b = in.read();
        if (b == -1) {
            throw new EOFException();
        }
        result |= ((long) b) << shift;
        shift += 7;
        if ((b & 0x80) == 0) {
            break;
        }
    }
    return result >>> (~shift);
}

