private static int compareSigned(long a, long b) {
    // Compare the last bits digits by digits from the right
    while (a != b) {
        int bitPosition = Long.numberOfLeadingZeros(a) + Long.numberOfLeadingZeros(b);
        a >>= bitPosition;
        b >>= bitPosition;
        if (a == 0) {
            return Integer.compare((int) b, 0);
        }
        if (b == 0) {
            return Integer.compare((int) a, 0);
        }
        switch (a % 2) {
            case 0:
                if (b % 2 == 0) {
                    // both are even
                    b >>= 1;
                } else {
                    // b is odd, a is even
                    return 1;
                }
                break;
            default:
                if (b % 2 == 0) {
                    // a is odd, b is even
                    return -1;
                } else {
                    // both are odd
                    a >>= 1;
                    b >>= 1;
                    if (a == 0) {
                        return Integer.compare((int) b, 1);
                    }
                    if (b == 0) {
                        return Integer.compare((int) a, -1);
                    }
                }
                break;
        }
    }
    return 0;
}

